import { createElement, useState, useEffect, useRef } from '@wordpress/element';
import {
	Button,
	SelectControl,
	TextareaControl,
	Notice,
} from '@wordpress/components';
import { __ } from '@wordpress/i18n';
import { useWorkspace } from './context';
import { skillText } from './skillTranslations.mjs';

/**
 * Language editing and explicit review of provider-generated drafts.
 * @param {Object} props       Component properties.
 * @param {Object} props.skill Shared skill.
 * @return {Object} Controls.
 */
export function SkillTranslationControls( { skill } ) {
	const w = useWorkspace();
	const [ target, setTarget ] = useState(
		w.skillLanguage === 'en' ? 'mn' : 'en'
	);
	const [ draft, setDraft ] = useState( null );
	const [ busy, setBusy ] = useState( false );
	const [ error, setError ] = useState( '' );
	const alive = useRef( true );
	useEffect( () => {
		alive.current = true;
		return () => {
			alive.current = false;
		};
	}, [] );
	const translate = async () => {
		setBusy( true );
		setError( '' );
		setDraft( null );
		try {
			const result = await window.wp.apiFetch( {
				path: `/ohmylms/v1/skills/${ skill.term_id }/translate`,
				method: 'POST',
				data: {
					locale: target,
					source: {
						name: skillText( skill, w.skillLanguage, 'name' ),
						objective: skillText( skill, w.skillLanguage ),
						description: skillText(
							skill,
							w.skillLanguage,
							'description'
						),
					},
				},
			} );
			if ( alive.current ) {
				setDraft( result );
			}
		} catch ( problem ) {
			if ( alive.current ) {
				setError(
					problem.message || __( 'Translation failed.', 'ohmylms' )
				);
			}
		} finally {
			if ( alive.current ) {
				setBusy( false );
			}
		}
	};
	return (
		<section aria-label={ __( 'Skill languages', 'ohmylms' ) }>
			<SelectControl
				label={ __( 'Editing language', 'ohmylms' ) }
				value={ w.skillLanguage }
				options={ [
					{ value: 'original', label: __( 'Original', 'ohmylms' ) },
					{ value: 'en', label: 'English' },
					{ value: 'mn', label: 'Монгол' },
				] }
				onChange={ w.setSkillLanguage }
				disabled={ busy || w.pending }
			/>
			{ w.skillLanguage !== 'original' &&
				! skill.translations?.[ w.skillLanguage ]?.name && (
					<p>
						{ __(
							'No translation saved yet. The original text is shown as a starting point; edit it to save this language.',
							'ohmylms'
						) }
					</p>
				) }
			<p>
				{ __(
					'Automatic translation sends this skill text to your configured AI provider. Review the draft before saving.',
					'ohmylms'
				) }
			</p>
			<SelectControl
				label={ __( 'Translate into', 'ohmylms' ) }
				value={ target }
				options={ [
					{ value: 'en', label: 'English' },
					{ value: 'mn', label: 'Монгол' },
				] }
				onChange={ ( value ) => {
					setTarget( value );
					setDraft( null );
				} }
				disabled={ busy }
			/>
			<Button
				variant="secondary"
				onClick={ translate }
				disabled={ busy || w.pending }
				isBusy={ busy }
			>
				{ createElement(
					'span',
					null,
					__( 'Translate automatically', 'ohmylms' )
				) }
			</Button>
			{ error && (
				<Notice status="error" isDismissible={ false }>
					{ error }
				</Notice>
			) }
			{ draft && (
				<div>
					<TextareaControl
						label={ __(
							'Translation draft: short title',
							'ohmylms'
						) }
						value={ draft.name }
						maxLength={ 190 }
						onChange={ ( name ) => setDraft( { ...draft, name } ) }
					/>
					<TextareaControl
						label={ __(
							'Translation draft: learning objective',
							'ohmylms'
						) }
						value={ draft.objective ?? draft.name }
						maxLength={ 2000 }
						onChange={ ( objective ) =>
							setDraft( { ...draft, objective } )
						}
					/>
					<TextareaControl
						label={ __( 'Translation draft: notes', 'ohmylms' ) }
						value={ draft.description }
						maxLength={ 2000 }
						onChange={ ( description ) =>
							setDraft( { ...draft, description } )
						}
					/>
					<Button
						variant="primary"
						disabled={ w.pending || ! draft.name.trim() }
						onClick={ async () => {
							if (
								( await w.actions.saveSkill( skill, {
									translations: { [ target ]: draft },
								} ) ) &&
								alive.current
							) {
								w.setSkillLanguage( target );
								setDraft( null );
							}
						} }
					>
						{ __( 'Save translation', 'ohmylms' ) }
					</Button>
					<Button
						variant="tertiary"
						onClick={ () => setDraft( null ) }
					>
						{ __( 'Discard draft', 'ohmylms' ) }
					</Button>
				</div>
			) }
		</section>
	);
}
